quests[28933] = { id = 28933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", sourceObjective = "Ehrt die Flamme des Kraters von Un'Goro.", sourceObjectiveStatus = "unverified-source-field" }
quests[28934] = { id = 28934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: offenbar in Uldum, direkt östlich vom Grab des Khartut, in der Nähe des Zugangs von Tanaris. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Techniker der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport östlich vom Grab des Khartut in Uldum zu zerstören und kehrt zu Inspektor Snip Schnappbolz in Sturmwind zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[28935] = { id = 28935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: offenbar in Uldum, direkt östlich vom Grab des Khartut, in der Nähe des Zugangs von Tanaris. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Techniker der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport östlich vom Grab des Khartut in Uldum zu zerstören und kehrt zu Inspektor Snap Schnappbolz in Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[28936] = { id = 28936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diva-Dilemma", sourceObjective = "Tötet 6 Naga.", sourceObjectiveStatus = "unverified-source-field" }
quests[28937] = { id = 28937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alliance Breadcrumb", description = "Monster! Da waren Monster, sage ich!\n\nUnser Schiff ist südlich von Stromgarde vor Anker gegangen, aber die Küste wimmelt nur so vor merkwürdigen Kreaturen.\n\nIhre hässlichen Fratzen zu sehen und ihre komischen Gurgelgeräusche zu hören reicht mir. Ich habe mich aus dem Staub gemacht, bevor klar wurde, was sie im Schilde führen. Ihr geht besser meinen Schiffskameraden helfen, {name}!", sourceObjective = "Sprecht mit Lady Gurga in der Faldirbucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[28938] = { id = 28938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet die Kinder", sourceObjective = "Rettet 6 Murlocbabys.", sourceObjectiveStatus = "unverified-source-field" }
