quests[29013] = { id = 29013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten" }
quests[29014] = { id = 29014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten" }
quests[29015] = { id = 29015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Minenarbeiters Vermögen", description = "He, {race}, seid Ihr an Schätzen interessiert? Wusste ich es doch, dass das Eure Aufmerksamkeit gewinnen würde.\n\nHier an den Flussdocks geht das Gerücht um, dass einer der Minenarbeiter in der Felsadermine der Venture Company nordöstlich von hier einen Smaragd von der Größe Eurer Faust gefunden hat.\n\nIch kenne ein paar Käufer, die daran interessiert wären, so etwas in die Finger zu bekommen, und ich wäre bereit, halbe-halbe beim Verkauf mit Euch zu machen. Seid Ihr dabei?", sourceObjective = "Erhaltet den Katzenaugensmaragd von einem der Vorarbeiter oder Vollstrecker der Venture Co.", progress = "Wenn wir nur wüssten, welcher der Minenarbeiter den Smaragd gefunden hat, wäre das der reinste Spaziergang...", completion = "Seht Euch nur an, wie riesig das Ding ist! Wir sind reich! Mal sehen, wenn man nach dem in Lorenhall gültigen Kurs für Edelsteine geht, sollte ich Euren Anteil berechnen können - fünfzig Prozent, selbstredend!\n\nAlso, dann sehen wir mal... Ich denke, damit sollten wir quitt sein. Es war mir ein Vergnügen, Geschäfte mit Euch zu machen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29016] = { id = 29016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten" }
quests[29017] = { id = 29017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten" }
quests[29018] = { id = 29018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten" }
quests[29019] = { id = 29019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten" }
quests[29020] = { id = 29020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten" }
quests[29021] = { id = 29021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Samophlang", description = "Die Venture Company hat weit nördlich von hier, westlich des Schlickmoores, eine kleine Forschungseinrichtung errichtet. Was die Leute dort tun, weiß ich nicht genau, aber ich habe herausgefunden, dass sie dort mit etwas experimentieren, das \"Samophlang\" genannt wird.\n\nWas zum Teufel ist ein Samophlang? Naja, was immer es auch ist, ich möchte es untersuchen, also brauche ich jemanden, der eines beschafft.\n\nIch habe ein Exemplar der Bedienungsanleitung für ihr Steuersystem in die Finger bekommen; Ihr solltet also herausfinden können, wie man das Samophlang daraus entfernt.", sourceObjective = "Verschafft Euch Zugang zur Steuerkonsole in der Forschungseinrichtung der Venture Company.\n\nBereitgestellter Gegenstand:", completion = "Eine Vielzahl von Knöpfen, Hebeln und blinkenden Lampen sind etwas ungeordnet auf der Oberfläche der Steuerkonsole angebracht. Eine kleine Anzeige deutet darauf hin, dass die Apparatur momentan optimal funktioniert und dass die Ventile eins bis drei derzeit geöffnet sind. Rechts unten an der Seite der Steuerkonsole befindet sich ein kleines Schlüsselloch.", sourceObjectiveStatus = "unverified-source-field" }
quests[29022] = { id = 29022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Samophlang", description = "Die drei Steuerventile sind momentan geöffnet. Die verschiedenen Anzeigen der Steuerkonsole führen Euch zu der Annahme, dass man sie zunächst schließen muss, bevor der Apparat ausgeschaltet werden kann.", sourceObjective = "Schließt das Treibstoffzufuhrventil, das Regelventil und das Hauptsteuerventil, und benutzt dann noch einmal die Steuerkonsole.", progress = "Blinkende Lampen auf der Steuerkonsole deuten darauf hin, dass die Hauptsteuerventile noch nicht geschlossen wurden.", completion = "Die Lampen erlöschen, sobald die drei Steuerventile geschlossen werden. Grüne Lampen wechseln langsam zu gelb, und der Schalter zur Steuerung des Apparats kann jetzt betätigt werden. Da alle Ventile geschlossen sind, könnt Ihr ihn ausschalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29023] = { id = 29023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Samophlang", description = "Da der Apparat jetzt ausgeschaltet ist, kann die Steuerkonsole geöffnet und das Samophlang entfernt werden. Alles andere sollte unangetastet bleiben und Ihr benötigt jetzt nur noch den Schlüssel, mit dem die Konsole geöffnet werden kann.", sourceObjective = "Besorgt Euch bei Tüftler Kichers den Konsolenschlüssel.", progress = "Die Lampen der Konsole leuchten schwach und sämtliche Anzeigen und Skalen stehen auf null, alles ist im Leerlauf.", completion = "Kaum wird der Schlüssel herumgedreht, öffnet sich die Steuerkonsole. Oben auf der Konsole erlischt eine rote Lampe und das Terminal führt keinen Strom mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[29024] = { id = 29024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Samophlang", description = "Nach dem Öffnen der Front der Steuerkonsole zeigt sich ein dichtes Gewirr aus Kabeln, Schläuchen und anderen seltsamen, mechanischen Objekten - die meisten davon scheinen keinen praktischen Nutzen zu haben. Ihr schiebt sie beiseite und arbeitet Euch tiefer in die Konsole vor, bis Ihr schließlich das Samophlang gefunden habt. Mit einem Ruck zieht Ihr es aus der Halterung.", sourceObjective = "Bringt das Samophlang zu Stotterspritter in Düsentopfs Außenposten im Nördlichen Brachland zurück.", progress = "Ihr seid zurück, {name}! Habt Ihr das Samophlang?", completion = "Das ist... äh... interessant... wirklich. Ein komplexes Gerät wie dieses sollte von einem Team fähiger Ingenieure in einem sterilisierten Raum analysiert werden, die in mühsamer Kleinarbeit jedes Bauteil einzeln unter kontrollierten Bedingungen nachkonstruieren.\n\nAber wer hat schon diese Zeit?\n\nSchmeißen wir das Teil einfach an und schauen mal was passiert...", sourceObjectiveStatus = "unverified-source-field" }
quests[29026] = { id = 29026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenikee Kübelbolz", description = "Ich glaube, ich habe das Ding wirklich kaputt gemacht: sieht so aus, als hätte ich einen der tragenden Fluxoren in die Speichen des Deregulatorgetriebes gehämmert. Aber das können wir ganz einfach beheben. Ich kenne eine Expertin für 3-fach Expansionskolbenantriebe, die liebend gern ein Samophlang in die Finger bekommen würde. Bringt das zerbrochene Samophlang zu Wenikee Kübelbolz südlich des Schutzwalls von Mor'shan und sie wird es schon zusammenflicken.\n\nHe, Ihr müsst noch nicht einmal zu Fuß gehen. Das ist die perfekte Gelegenheit, meinen persönlichen Personenporter zu testen!", sourceObjective = "Bringt das zerbrochene und ramponierte Samophlang zu Wenikee Kübelbolz. Sprecht mit Brak, um direkt zu ihr teleportiert zu werden.", progress = "Ich bin gerade sehr beschäftigt, {class}. Wenn Ihr also nichts für mich habt, dann solltet Ihr am besten einfach wieder gehen...", completion = "Oh, was haben wir denn hier? Ein Samophlang, sagt Ihr? Was ist ein Samophlang?\n\nAh, jetzt schaut doch nur, es bewegt sich, wenn man es anfasst. Und im Inneren ist das Geräusch eines komplizierten Getriebes. Oh Mann! Ich will das Ding unbedingt reparieren und sehen, was es tut, Ihr nicht?", sourceObjectiveStatus = "unverified-source-field" }
quests[29027] = { id = 29027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schraubnieten", description = "Ich möchte das Samophlang reparieren, aber dazu brauche ich ein paar Dinge. Ich habe keine 17,5er Schraubnieten mehr, und davon werde ich für meine Arbeit hier eine ganze Menge brauchen.\n\nLeider ist der nächstgelegene Ort, an dem man sie bekommen kann, der Hof der Brennenden Klinge im Südwesten. Der Ort wird schwer bewacht, seid also vorsichtig. Durchsucht die Werkzeugkisten und kehrt zu mir zurück, wenn Ihr genug Schraubnieten gesammelt habt.", sourceObjective = "Sammelt 10 Schraubnieten aus den Wergzeugkisten um den Hof der Brennenden Klinge im Südwesten.", progress = "Habt Ihr die Schraubnieten, {name}? Ständig muss ich mir dieses Samophlang ansehen - ich kann es gar nicht erwarten, endlich daran herumzubasteln.", completion = "Prima, Ihr habt sie! Jetzt kann ich mich endlich an die Arbeit machen...", sourceObjectiveStatus = "unverified-source-field" }
quests[29028] = { id = 29028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinein nach Jaedenar", description = "Der Schattenrat verdirbt diesen einst wunderschönen Wald von ihrer Festung Jaedenar aus, die nordwestlich von hier liegt.\n\nEiner der Unseren ist nun dort verschwunden. Wir haben einen einzelnen Späher mit Namen Andalar Dämmertal in der Hoffnung losgeschickt, dass er die Reihen des Feindes heimlich lichten kann.\n\nSeit Tagen haben wir nichts von ihm gehört und befürchten das Schlimmste. Es besteht eine kleine Chance, dass er noch am Leben ist. {name}, bitte brecht sofort auf und macht ihn ausfindig!", sourceObjective = "Macht Andalar Dämmertal in Jaedenar ausfindig.", sourceObjectiveStatus = "unverified-source-field" }
quests[29029] = { id = 29029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sterbendes Wissen", description = "<Das verderbte Wasser blubbert und schäumt, als wolle es vor sich selbst entkommen.>\n\nBringt dieses Wasser zu unserem Feldspäher. Er sollte in der Lage sein, es für unseren Angriff auf die Verteidigung der Schattenfeste zu läutern!", sourceObjective = "Bringt die gefüllte Feldflasche zu Andalar Dämmertal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29030] = { id = 29030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, {name}?", sourceObjective = "Ehrt das Freudenfeuer des Irdenen Rings auf dem Hyjal.", completion = "Ehrt die Flamme des Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29031] = { id = 29031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, {name}?", sourceObjective = "Ehrt das Freudenfeuer des Irdenen Rings in Vashj'ir.", completion = "Ehrt die Flamme von Vashj'ir.", sourceObjectiveStatus = "unverified-source-field" }
quests[29032] = { id = 29032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solange sie noch jung sind", description = "Ich kann Euch beibringen, wie man einen Winterquellfrostsäbler reitet, aber das braucht Zeit und Hingabe. Damit das funktioniert, müssen sowohl Säbler als auch Reiter hervorragend ausgebildet sein und es muss zwischen ihnen tiefempfundenes Vertrauen bestehen.\n\nDie Jungtiere sind für dieses Training nur empfänglich, wenn sie in jungen Jahren mit ihrem Reiter vertraut gemacht werden. In den Bauen rund um den Frostsäblerfelsen gibt es Junge, die das richtige Alter haben, um ihre Ausbildung zu beginnen. Wenn Ihr mir helft, die vielversprechendsten dieser Jungtiere einzusammeln, gestatte ich Euch, dass Ihr Euer Training mit Eurem eigenen Jungtier aufnehmt.", sourceObjective = "Sammelt 8 Frostsäblerjunge aus den Bauen rund um den Frostsäblerfelsen.", progress = "Wir müssen die Säblerjungen in unsere Obhut nehmen, solang sie noch jung genug sind, uns anzunehmen. Wenn sie zu alt werden, bleiben sie ihr Leben lang wild.", completion = "Diese Jungen haben genau das richtige Alter, um ihre Ausbildung zu beginnen. Einige von ihnen haben sogar die nötigen Eigenschaften, um als Reittiere zu dienen. Wie versprochen werde ich eines dieser Jungtiere für Euch zum Abrichten aussuchen. Dieser Bursche hier scheint Euch zu mögen.\n\nIch werde die gewöhnlichen, etwas zahmeren Jungen für den Markt in Darnassus ausbilden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29034] = { id = 29034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie schnell sie heranwachsen", description = "Ich glaube, dieser kleine Bursche passt gut zu Euch.\n\nDieses Junge wird eine Menge Aufmerksamkeit brauchen, damit es groß und stark wird. Ihr solltet mindestens einmal täglich nach Eurem Jungen sehen. Die beste Methode, ein Vertrauensverhältnis mit ihm aufzubauen, besteht darin, es zu füttern und zu umsorgen.\n\nWenn Euer Junges heranwächst, wird es seine alten Schnurrhaare abwerfen und neue, seiner Größe angemessene bekommen. Bringt mir Euer Junges zusammen mit ein paar Materialien für Euren Sattel, sobald es zwanzig Schnurrhaare verloren hat.", sourceObjective = "Sammelt 20 Schnurrhaare eines Winterquelljungen, die von Eurem Winterquelljungen abgeworfen worden sind. Bringt die Schnurrhaare, 20 Runenstoff, 20 unverwüstliches Leder und 80 Gold zu Rivern Frostwind.", progress = "Wie geht es Eurem jungen Säbler?", completion = "Wie es scheint, habt Ihr hervorragende Arbeit bei der Aufzucht Eures Jungen geleistet, {name}. Euer Säbler ist zu einem starken, gesunden und loyalen Begleiter herangewachsen. Ihr passt gut zueinander.\n\nNehmt diese Pfeife. Euer Winterquellfrostsäbler wird Eurem Ruf folgen, wenn Ihr mit ihm reiten wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29035] = { id = 29035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Katzenhunger", description = "Euer Winterquelljunges schaut Euch an und leckt sich die Lippen. Die kleine Katze muss Hunger haben und es ist Eure Aufgabe, geeignetes Futter für Euren Schützling zu finden.\n\nRivern Frostwind hat erwähnt, dass er immer etwas Fleisch von Splitterzahnbären vorrätig hat, mit dem er seine Frostsäblerjungen füttert. Vielleicht mag Euer Junges ja auch etwas Splitterzahnfleisch. Überall in Winterquell kann man verschiedene Arten von Splitterzahnbären finden.", sourceObjective = "Sammelt 6 Stück Splitterzahnfleisch von beliebigen Splitterzahnbären in Winterquell und verfüttert sie an Euer Winterquelljunges.", completion = "Euer Winterquelljunges sieht glücklich und zufrieden aus und scheint bereit zu sein, sich für ein Schläfchen zusammenzurollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29036] = { id = 29036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, {name}?", sourceObjective = "Ehrt das Freudenfeuer des Irdenen Rings in Tiefenheim.", completion = "Ehrt die Flamme von Tiefenheim.", sourceObjectiveStatus = "unverified-source-field" }
quests[29037] = { id = 29037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Leihgabe\" von den Winterfellen", description = "Euer Junges sieht Euch erwartungsvoll an. Was es wohl jetzt möchte?\n\nDie kleine Katze leckt sich die Lippen. Es muss wohl wieder Zeit zum Essen sein! Als <Ersatzvater/Ersatzmutter> für das Junge ist es Eure Aufgabe, für Futter zu sorgen, bis es selbst auf die Jagd gehen kann.\n\nAber was, wenn Ihr jemand anderem das Jagen überlassen würdet? Die Winterfellfurbolgs in Winterquell haben für gewöhnlich eine Menge Räucherfleisch in ihren beiden Lagern. Ein paar Stücke würde doch niemand vermissen und Euer Junges könnte etwas Neues probieren.", sourceObjective = "Sammelt 6 Stück Räucherfleisch aus einem der beiden Lager der Winterfellfurbolgs in Winterquell und verfüttert sie an Euer Winterquelljunges.", completion = "Euer Junges sieht fürs Erste zufrieden aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[29038] = { id = 29038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagen üben", description = "Euer Winterquelljunges spielt mit Euren Händen. Ohne Spielgefährten hat das Kätzchen nur selten Gelegenheit, seine Jagdfähigkeiten zu üben.\n\nVielleicht solltet Ihr Euer Junges Jagd auf die kleinen Arktishasen, die ihre Baue im nördlichen Winterquell graben, machen lassen. Bringt Euer Junges in die Nähe der Schneewehen, die die Hasenbaue bedecken, und wartet, bis das Junge seinen Instinkten folgt.", sourceObjective = "Bringt Euer Junges 5 Mal in die Nähe von schneebedeckten Bauen im nördlichen Winterquell, damit es lernt, wie man Arktishasen jagt.", completion = "Euer Winterquelljunges sieht müde, zufrieden und vielleicht etwas erfahrener aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[29039] = { id = 29039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagen üben", description = "Euer Winterquelljunges spielt mit Euren Händen. Ohne Spielgefährten hat das Kätzchen nur selten Gelegenheit, seine Jagdfähigkeiten zu üben.\n\nVielleicht solltet Ihr Euer Junges Jagd auf die kleinen Arktishasen, die ihre Baue im nördlichen Winterquell graben, machen lassen. Bringt Euer Junges in die Nähe der Schneewehen, die die Hasenbaue bedecken, und wartet, bis das Junge seinen Instinkten folgt.", sourceObjective = "Bringt Euer Junges 5 Mal in die Nähe von schneebedeckten Bauen im nördlichen Winterquell, damit es lernt, wie man Arktishasen jagt.", completion = "Euer Junges sieht müde, zufrieden und vielleicht etwas erfahrener aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[29040] = { id = 29040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kätzchens erstes Spielzeug", description = "Das Winterquelljunge spielt mit einem kleinen Fellknäuel, das von einem großen Tier zu stammen scheint. Es sieht zwar so aus, als ob Euer Junges Spaß an dem neuen Spiel hat, Ihr fragt Euch aber, ob es an einem richtigen Katzenspielzeug nicht mehr Spaß haben würde.\n\nMit etwas Leder von einem Yetipelz und einigen Federn von den wahnsinnigen Mondkin könntet Ihr ein brauchbares Spielzeug herstellen. Ihr braucht einen Balg von den Yetis in den Eisdistelbergen südöstlich der Ewigen Warte und Federn von den Mondkin im Versteckten Hain oder dem Eulenflügeldickicht.", sourceObjective = "Erhaltet einen schweren Yetibalg und 5 Wildekinfedern. Stellt daraus ein Katzenspielzeug aus Winterquell her und benutzt es, um mit Eurem Winterquelljungen zu spielen.", completion = "Euer Winterquelljunges scheint sein neues Spielzeug zu lieben, aber ob das Spielzeug den Enthusiasmus des Kätzchens überlebt ist ungewiss.", sourceObjectiveStatus = "unverified-source-field" }
quests[29051] = { id = 29051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kätzchens erstes Spielzeug", description = "Das Winterquelljunge spielt mit einem kleinen Fellknäuel, das von einem großen Tier zu stammen scheint. Es sieht zwar so aus, als ob Euer Junges Spaß an dem neuen Spiel hat, Ihr fragt Euch aber, ob es an einem richtigen Katzenspielzeug nicht mehr Spaß haben würde.\n\nMit etwas Leder von einem Yetipelz und einigen Federn von den wahnsinnigen Mondkin könntet Ihr ein brauchbares Spielzeug herstellen. Ihr braucht einen Balg von den Yetis in den Eisdistelbergen südöstlich der Ewigen Warte und Federn von den Mondkin im Versteckten Hain oder dem Eulenflügeldickicht.", sourceObjective = "Erhaltet einen schweren Yetibalg und 5 Wildekinfedern. Stellt daraus ein Katzenspielzeug aus Winterquell her und benutzt es, um mit Eurem Winterquelljungen zu spielen.", completion = "Euer Winterquelljunges scheint sein neues Spielzeug zu lieben, aber ob das Spielzeug den Enthusiasmus des Kätzchens überlebt ist ungewiss.", sourceObjectiveStatus = "unverified-source-field" }
quests[29052] = { id = 29052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Katzenhunger", description = "Euer Winterquelljunges schaut Euch an und leckt sich die Lippen. Die kleine Katze muss Hunger haben und es ist Eure Aufgabe, geeignetes Futter für Euren Schützling zu finden.\n\nRivern Frostwind hat erwähnt, dass er immer etwas Fleisch von Splitterzahnbären vorrätig hat, mit dem er seine Frostsäblerjungen füttert. Vielleicht mag Euer Junges ja auch etwas Splitterzahnfleisch. Überall in Winterquell kann man verschiedene Arten von Splitterzahnbären finden.", sourceObjective = "Sammelt 6 Stück Splitterzahnfleisch von beliebigen Splitterzahnbären in Winterquell und verfüttert sie an Euer Winterquelljunges.", progress = "Euer Winterquelljunges sieht Euch an als wolle es sagen \"Das soll alles sein?\".", completion = "Euer Winterquelljunges sieht glücklich und zufrieden aus und scheint bereit zu sein, sich für ein Schläfchen zusammenzurollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29053] = { id = 29053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Leihgabe\" von den Winterfellen", description = "Euer Junges sieht Euch erwartungsvoll an. Was es wohl jetzt möchte?\n\nDie kleine Katze leckt sich die Lippen. Es muss wohl wieder Zeit zum Essen sein! Als <Ersatzvater/Ersatzmutter> für das Junge ist es Eure Aufgabe, für Futter zu sorgen, bis es selbst auf die Jagd gehen kann.\n\nAber was, wenn Ihr jemand anderem das Jagen überlassen würdet? Die Winterfellfurbolgs in Winterquell haben für gewöhnlich eine Menge Räucherfleisch in ihren beiden Lagern. Ein paar Stücke würde doch niemand vermissen und Euer Junges könnte etwas Neues probieren.", sourceObjective = "Sammelt 6 Stück Räucherfleisch aus einem der beiden Lager der Winterfellfurbolgs in Winterquell und verfüttert sie an Euer Winterquelljunges.", completion = "Euer Junges sieht fürs Erste zufrieden aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[29054] = { id = 29054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stinkbomben los!", description = "Grüße, {class}! Ich hoffe, Ihr genießt die Schlotternächte. Ach, genug geplaudert... kommen wir zum Geschäftlichen. Unterstadt. Sie setzen Hexen und widerwärtige Magie ein, um Angriffe auf unsere Stadt zu führen. Manch einer mag sagen \"ignoriert doch die Kindereien der Horde\". Ich aber sage \"zeigen wir's ihnen!\"\n\nSprecht mit meiner Schwester Gertrude und sie wird Euch dabei helfen, ein paar Stinkbomben auf Unterstadt abzuwerfen.", sourceObjective = "Sprecht mit Gertrude Fenlow, um Zugang zu einem Besen zu bekommen. Werft dann Stinkbomben auf Unterstadt ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[29066] = { id = 29066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gute Neuigkeiten... und schlechte Neuigkeiten", description = "<Schwarzhorn hat die Macht von Thol'embaars Überresten verwendet, um seine Fesseln loszuwerden. Aber immerhin scheint sich das Inferno zu legen.>\n\n<Matookla wird von dem Geschehen hier erfahren wollen. Sie wartet auf Euch am Hain von Aessina.>", sourceObjective = "Sprecht mit Matookla am Hain von Aessina auf dem Hyjal.", completion = "Was? Schwarzhorn hat Euch geholfen, das Inferno zu bekämfen und ist dann verschwunden? Dieses verschlagene Wiesel!\n\nMacht Euch keine Vorwürfe, {name}. Er hatte sich diesen Plan vermutlich in dem Moment ausgedacht, in dem er die Flammen den Berg hinaufsteigen sehen hat. Wir werden uns später um ihn kümmern müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29067] = { id = 29067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Tränke", description = "Tränke, Tränke, Tränke. Was ich Euch alles über Tränke beibringen könnte!\n\nBringt mir Proben Eurer Arbeit, damit ich weiß, dass Ihr bereit dazu seid.\n\nVergesst nicht, {name}, dass Ihr nur EINE Spezialisierung erlernen könnt, Euch also die Elixier- und Transmutationsspezialisierung danach nicht mehr angeboten werden.", sourceObjective = "Bringt eine große Anzahl Tränke zu einem Alchemielehrer in einer beliebigen Hauptstadt.", progress = "Habt Ihr die Tränke?", completion = "Hervorragend!", sourceObjectiveStatus = "unverified-source-field" }
quests[29071] = { id = 29071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Eile nach Sturmwind!", sourceObjective = "Veteranen von Nordend, König Wrynn und die Allianz benötigen Eure Hilfe! Sturmwind und die Allianz werden von Todesschwinge und seinen Anhängern des Schattenhammerkults auf beispiellose Weise bedroht!\n\nIhr findet in diesem Brief einen Ruhestein, der Euch nach Sturmwind transportieren wird. Die Krone hat für Unterkunft für alle zurückkehrenden Helden im Gasthaus \"Zum Goldenen Fass\" im Zwergendistrikt gesorgt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29073] = { id = 29073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Eile nach Orgrimmar!", sourceObjective = "Veteranen von Nordend, Kriegshäuptling Garrosh befiehlt Euch umgehend nach Orgrimmar zurückzukehren! Ihr werdet die Klinge sein, die die Horde gegen Todesschwinge und seine Schattenhammergefolgsleute führen wird.\n\nBenutzt den in diesem Schreiben eingeschlossenen Ruhestein, um Euch nach Orgrimmar zu transportieren. Unsere Verbündeten erwarten Eure Rückkehr, Held.", sourceObjectiveStatus = "unverified-source-field" }
quests[29074] = { id = 29074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Zeit zum Feiern", description = "Frohe Grüße, {class}!\n\nDie Schlotternächte sind eine Zeit des Feierns und der Besinnlichkeit, obwohl es scheint, dass viele von uns vergessen haben, warum. In der Tat sind manche Aspekte des Festes, wie der Weidenmann, über die Zeit verlorengegangen... bis jetzt, mit der Rückkehr von Gilneas in die Arme der Allianz.\n\nBegebt Euch vor die Tore Sturmwinds und sprecht mit Celestine Erntedank. Sie wird Euch mehr von der Weidenmannzeremonie erzählen.", sourceObjective = "Sprecht mit Celestine Erntedank vor den Toren Sturmwinds.", sourceObjectiveStatus = "unverified-source-field" }
quests[29075] = { id = 29075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Zeit des Gewinnens", description = "Grüße, {class}. Der Weidenmann, der vor Euch steht, symbolisiert das Ich. Die Flammen, die ihn verbrennen, sind reinigendes Feuer.\n\nDie Tradition besagt, dass wir unsere Bürden ablegen und sie dem Feuer übergeben. Wir entledigen uns allem, was uns belastet und bereiten uns auf den Winter vor und erlangen Klarheit und Frieden. Nehmt doch an dieser Tradition teil, {class}.\n\nNehmt einen Zweig von dem nahegelegenen Freudenfeuer und werft ihn nach dem Weidenmann.", sourceObjective = "Benutzt das Freudenfeuer vor dem Weidenmann.", sourceObjectiveStatus = "unverified-source-field" }
quests[29078] = { id = 29078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlagt sie zurück!", description = "Noch ein Allianzrekrut, hm? Ich bin Marschall McBride, Kommandant dieser Garnison. Von Eurem Schlag sieht man hier sehr viele, {race}, aber wir können Eure Hilfe sicher brauchen.\n\nIhr kommt gerade rechtzeitig. Die Schwarzfelsorcs haben es geschafft, sich durch eine Lücke im Berg nach Nordhain einzuschleichen. Meine Soldaten tun ihr Bestes, sie zurückzudrängen, aber ich befürchte, wir werden bald überrant werden.\n\nGeht nach Nordwesten in den Wald und tötet die angreifenden Kampfworgs des Schwarzfels! Helft meinen Soldaten!", sourceObjective = "Tötet 6 Kampfworgs des Schwarzfels.", completion = "Ihr habt uns etwas Zeit verschafft, {name}, aber jetzt müssen wir uns um größere Probleme Kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[29079] = { id = 29079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgs im Schafspelz", description = "Die einfallenden Orcs sind keine Narren. Sie schätzen uns ab, stellen sicher, dass ihre Angriffe zu ihrem Vorteil sein werden.\n\nIm Wald nordwestlich sind Spione der Schwarzfelsorcs. Sie spähen uns durch Handfernrohre aus, überwachen jeden unserer Schritte - und warten. Ich will, dass Ihr sie angreift!\n\nTötet die Spione der Schwarzfelsorcs! Wir müssen ihnen zeigen, dass wir wissen, dass sie uns beobachten und dass wir vorbereitet sind!", sourceObjective = "Tötet 8 Spione des Schwarzfels.", completion = "Hervorragende Arbeit, {name}. Es hat sich herausgestellt, dass Ihr ein echter Gewinn für die Garnison seid.\n\nEs steht Euch frei, mit unseren Ausbildern in und um die Abtei herum zu sprechen, wenn Ihr Eure Kampfkünste schulen wollt.\n\nWenn Ihr soweit seid habe ich einen weiteren Auftrag für Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[29080] = { id = 29080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stürzt Euch in die Schlacht!", description = "Ich habe hier eine dringende Nachricht von Unteroffizier Willem. Wie es aussieht, haben die Schwarzfelsorcs goblinische Auftragsmörder angeheuert. Sie haben unser Bataillon hinter der Abtei überfallen. Willem bittet mich, ihm einen Helden zu schicken. Ihr müsst ihnen helfen, {name}!\n\nIhr findet Unteroffizier Willem nördlich von der Abtei im Kommandozelt. Los!", sourceObjective = "Meldet Euch bei Unteroffizier Willem hinter der Abtei von Nordhain im Wald von Elwynn", completion = "Es ist wahr, wir wurden überfallen. Ich wage es nicht, noch mehr Soldaten dort hinauszuschicken und sie auch noch zu verlieren. Ich brauche einen Freiwilligen. Jemanden, der bereit ist, sein Leben aufs Spiel zu setzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29081] = { id = 29081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie haben Auftragsmörder losgeschickt", description = "Habt Ihr jemals einen Goblin gesehen, {name}? Diese jämmerlichen, kleinen, grünhäutigen Monster mögen nur zwei Dinge: Gold und sich selbst.\n\nDie Schwarzfelsorcs haben sich goblinische Auftragsmörder zu Hilfe geholt, die unsere Soldaten töten sollen. Wenn Ihr zum Feld im Norden blickt, könnt Ihr schwach ihre Umrisse erkennen, wie sie im Gras umherschleichen.\n\nIhr müsst Euch dort hinbegeben und jeden Goblin töten, den Ihr zu Gesicht bekommt. Sie müssen kapieren, dass man sich nicht mit der Allianz anlegt!", sourceObjective = "Tötet 8 goblinische Auftragsmörder.", completion = "Ihr habt diesen Monstern eine Lektion erteilt! Sie werden es sich zweimal überlegen, bevor sie noch einen Mordauftrag der Orcs annehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29082] = { id = 29082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fürchtet nicht das Böse", description = "Habt Ihr Euch schon zum Heiligen Licht bekannt, <Bruder/Schwester>? Durch das Heilige Licht werden wir errettet! Das Heilige Licht versetzt mich in die Lage, diese überaus fordernden Soldaten zu heilen! Und durch das Heilige Licht werdet Ihr in der Lage sein, hinaus ins Feld nach Norden zu gehen, und unsere gefallenen Brüder zu retten!\n\nTragt dieses Gebetsbuch mit Euch ins Feld und wirkt die heilende Berührung des Lichts auf die Verwundeten.", sourceObjective = "Belebt 4 verletzte Soldaten von Sturmwind wieder.", progress = "Rettet unsere Soldaten!", completion = "Ich glaube, Ihr versteht nun, welche Macht dem Licht innewohnt. Das Licht spendet Hoffnung, Schwester, und das Licht lässt die Finsternis schwinden! GESEGNET SEI DAS LICHT!", sourceObjectiveStatus = "unverified-source-field" }
quests[29083] = { id = 29083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefahr gebannt", description = "Ausgezeichnete Arbeit, {name}! Sie werden uns definitiv nicht mehr in den Rücken fallen. Wir kümmern uns um die Nachzügler. Ich will, dass Ihr zurück zu Marschall McBride geht, der südlich von hier vor der Abtei von Nordhain steht. Lasst ihn wissen, dass die Situation mit den Goblins unter Kontrolle ist.\n\nLebt wohl, {class}.", sourceObjective = "Meldet Euch bei Marschall McBride vor der Abtei von Nordhain im Wald von Elwynn.", completion = "Dank Eurer Hilfe ist es uns gelungen, die nördlichen und westlichen Abschnitte von Nordhain zu sichern. Dennoch gibt es im Osten noch immer eine ziemlich große Ansammlung von Schwarzfeslorcs und sie haben damit begonnen, den Wald niederzubrennen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29084] = { id = 29084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zufälliger, klassischer Dungeon 35-39 (Erster)" }
quests[29085] = { id = 29085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zufälliger, klassischer Dungeon 35-39 (Nter)" }
quests[29086] = { id = 29086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konkurrenz? Pah!", description = "Ich bin nur ein kleiner Mann, der versucht, sich selbständig zu machen. Ich arbeite fleißig daran, den azerothischen Traum in die Tat umzusetzen, wisst Ihr?\n\nTja, kaum hatte ich mich hier niedergelassen, hat die Venture Co. nebenan entschieden, dass sie mich hier nicht wollen. Sie haben mich mit Drohbriefen schikaniert und dabei Wörter wie \"Unterlassungsklage\" benutzt.\n\nViel schlimmer ist, dass die Baupläne für meine neuste Maschine verschwunden sind und ich weiß genau, dass diese Langfinger sie gestohlen haben! Geht zum Schlickmoor und haut ein paar ihrer Arbeiter um. Ich bin mir sicher, dass sie meine Blaupausen haben!", sourceObjective = "Erhaltet 6 von Stotterspritters Blaupausen von Zwangsarbeitern, Söldnern oder Peons der Venture Co.", progress = "Ich kann gar nicht glauben, dass sie sich auf dieses Niveau herablassen würden. Habt Ihr meine Blaupausen zurückbekommen?", completion = "Danke, dass Ihr meine Blaupausen beschafft habt. Jetzt kann meine Arbeit an der Silberblitz X-831 weitergehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29087] = { id = 29087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlickuntersuchungen", description = "He, {name}, seht Ihr diese Fußabdrücke? Die sind gestern Nacht überall im Lager aufgetaucht! Es fehlt nichts, aber all unsere Habseligkeiten wurden... untersucht. Die schlammige Spur führt zurück zum Schlickmoor.\n\nDa hat jemand herumgeschnüffelt und das gefällt mir gar nicht. Könnt Ihr Euch nach Westen aufmachen und das Schlickmoor untersuchen? Seht nach, ob Ihr dort auch so eine Spur wie diese hier finden könnt!", sourceObjective = "Untersucht 5 schlammige Spuren im Schlickmoor.", sourceObjectiveStatus = "unverified-source-field" }
quests[29088] = { id = 29088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hyänenausrottung", description = "He, {name}, wir haben hier ein echtes Problem. Die Hyänenpopulation westlich des Schlickmoors nimmt Überhand und die werden langsam zu einer Bedrohung.\n\nWenn ich deren Radau noch eine Nacht ertragen muss, werd' ich noch verrückt! Vernon da drüben sagt, die Hyänen könnten sogar etwas mit dem Verschwinden eines seiner Schweine zu tun haben. So etwas kommt überhaupt nicht in die Tüte.\n\nKönntet Ihr ihre Reihen etwas lichten gehen? Ihr könnt sie im Westen finden. Dort lungern sie bei helllichtem Tage herum.", sourceObjective = "Tötet 6 Fleischreißerhyänen.", completion = "Auf Nimmerwiedersehen! Diese dreckigen Plagegeister bedeuten mehr Ärger als einem lieb sein kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[29089] = { id = 29089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlickbestie!", description = "Was auch immer da im Schlickmoor lauert scheint nicht humanoid zu sein. Den Überresten in der Umgebung der Spuren nach zu urteilen, ist es außerdem gefährlich.\n\nIhr entschließt Euch, den Spuren zum Boden des Sees zu folgen und nach dem Ruheplatz des Wesens zu suchen.", sourceObjective = "Untersucht den Schlafplatz der Schlickbestie und tötet was auch immer zum Vorschein kommt.", completion = "Ihr habt gesehen, wie Abwasserschlamm direkt in den See gepumpt wurde? Es würde mich nicht überraschen, wenn die Schlickbestie durch die Sorglosigkeit der Venture Co. entstanden wäre.", sourceObjectiveStatus = "unverified-source-field" }
quests[29090] = { id = 29090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Brennende Bedrohung", description = "Wer passt auf, was hinter uns vor sich geht, während wir uns ganz dem Kataklysmus widmen? Unsere Anführer rufen gegen Todesschwinge zu den Waffen und währenddessen plant die Brennende Klinge unseren Untergang.\n\nJetzt in diesem Moment strömen neue Rekruten und Vorräte zu der Farm im Südwesten. Mir steht der Sinn nicht danach, von der Brennenden Klinge in den Rücken gestochen zu werden.\n\n{name}, helft Ihr mir, dieses Schicksal abzuwenden? Geht und richtet unter ihnen ein Blutbad an, bevor es zu spät ist.", sourceObjective = "Tötet 8 Mitglieder der Brennenden Klinge auf dem Hof im Südwesten.", completion = "Danke, {name}. Ihr habt einem alten Orc heute Nacht zu einem etwas ruhigeren Schlaf verholfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29091] = { id = 29091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiheitsbewegung" }
quests[29092] = { id = 29092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setzt den Urahnen in Kenntnis", description = "Diese Informationen müssen an den gesamten Irdenen Ring weitergeleitet werden. Ich bin mir nicht sicher, wie wir vorgehen sollten, aber der Urahn, der Euch überhaupt erst diese Aufgabe gestellt hat, weiß es vielleicht. Bitte sucht diesen Urahnen auf und findet heraus, was zu tun ist - wir müssen etwas unternehmen!", sourceObjective = "Reist in eine Hauptstadt und sprecht mit dem Urahnen des Irdenen Rings.", completion = "Das sind in der Tat schlimme Neuigkeiten. Wir müssen alles in unserer Macht Stehende tun, um diesen Krieg zu verhindern.", sourceObjectiveStatus = "unverified-source-field" }
quests[29093] = { id = 29093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rund um den Schlund", description = "Einer meiner Freunde sagt, dass ein Dampfpanzermechaniker in Westfall Besucher seine Chopper fahren lässt. Mein Freund durfte sogar auf einem fahren!\n\nIch habe Leute auf Choppern am Waisenhaus vorbeifahren sehen. Die sind total laut und so ziemlich das Schnellste, das ich je gesehen habe! So einen will ich mal ausprobieren!\n\nKönnten wir zur Späherkuppe in Westfall reisen und einen dieser Chopper ausleihen? Bitte? Ich bin auch ganz artig und außerdem könnten wir dann dieses irre Riesenloch sehen, das aufgerissen wurde, als die Welt sich verändert hat!", sourceObjective = "Reist zur Späherkuppe in Westfall und steigt auf einen Mietchopper, um den Rasenden Schlund mit Eurem Waisenkind zu besichtigen.", completion = "Das war das Größte! Das will ich nächstes Jahr wieder machen. Wenn ich erwachsen bin, werde ich auch einen Chopper haben, aber den werde ich selbst bauen und alle meine Freunde auf eine Spritztour mitnehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29094] = { id = 29094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Hause katapultieren", description = "Sieht so aus, als wäre Eure Arbeit hier getan, {class}. Ihr kehrt besser zum Wegekreuz zurück.\n\nIhr habt Glück, denn der Prototyp meiner Silberblitz X-831 ist fertig und sie wartet nur auf eine Probefahrt. Was haltet Ihr davon, mir einen letzten Gefallen zu tun und eine kleine Spritztour zu machen?\n\nEiner meiner Assistenten wird Euch begleiten. Euer fahrbarer Untersatz wartet auf der Plattform hinter mir auf Euch. Springt einfach drauf, wenn Ihr bereit seid.", sourceObjective = "Genießt einen Ritt auf der Silberblitz X-831.", completion = "Ich dachte, mit Euch wäre es aus gewesen. Schön, dass Ihr noch in einem Stück seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[29095] = { id = 29095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung bei Thork", description = "Nun da die Bedrohung hier eingedämmt ist, solltet Ihr zum Wegekreuz zurückkehren. Thork möchte mit Euch sprechen.\n\nLebt wohl, Freund.", sourceObjective = "Meldet Euch bei Thork am Wegekreuz im Nördlichen Brachland.", completion = "Hallo {name}. Darsok hat mir von Euren Taten berichtet. Ihr seid der Horde wahrlich ein wertvoller {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29096] = { id = 29096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schließt Euch dem Konvoi von Mor'shan an", description = "Rocco Peitschenschwinger wartet auf Euch an der Straße, die nördlich aus dem Wegekreuz führt. Lasst ihn wissen, dass Ihr bereit seid, den Konvoi zu begleiten.", sourceObjective = "Sprecht mit Rocco Peitschenschwinger und fahrt mit dem Konvoi von Mor'shan nach Norden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29097] = { id = 29097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mor'shan Konvoirettung" }
quests[29099] = { id = 29099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mor'shan Konvoilieferung" }
quests[29100] = { id = 29100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bwembas Geist", description = "Es sind gefährliche Zeiten für uns Dunkelspeere. Die Zandalaritrolle versammeln alle Trollklans und hab'n vor, die Länder wiederzuerobern, die sie verlor'n hab'n.\n\nWir versuch'n alle zu warnen, die wir können. Aber es könnte zu spät sein.\n\nEin weiterer Dunkelspeertroll is' ins Schlingendorntal gegang'n, um die Leute zu warnen. Aber es is' nich' sicher, allein da durchzuwandern.\n\nHilf mir, ihn zu find'n und sicherzustell'n, dass die Leute im Schlingendorntal von der Bedrohung durch die Trollstämme erfahr'n.\n\nIch werd' meinen Geist mit deinem verbind'n. Wenn du ins Schlingendorntal gelangst, werd' ich dir helf'n können.", sourceObjective = "Warnt die Bewohner des Schlingendorntals und findet den anderen Abgesandten der Dunkelspeere.", completion = "Da siehst du's, {name}. Sieht aus, als würd'n wir einen Angriff auf die Gurubashi in Zul'Gurub anführ'n.\n\nDies sind dunkle Zeiten für uns Dunkelspeere. Aber für die Zandalaritrolle werd'n sie noch dunkler. Sie sind zu weit gegang'n.\n\nDu bist gut zu Bwemba gewes'n, hoffentlich wirst du weiter das ganze Schlingendorntal unterstütz'n.\n\nMög'n die Geister mit dir sein, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29101] = { id = 29101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ab ins Wasser!", description = "Babyschildkröten sind so süß, auch wenn sie manchmal ein bisschen bissig sein können.\n\n<Mylune hält einen verbundenen Finger hoch.>\n\nAber auf ihren kurzen Beinchen sind sie so langsam, da können sie den Feuerwesen, die den Hyjal angreifen, nicht entkommen!\n\n<Mylune klatscht mit den Händen.>\n\nBITTE rettet sie, {name}! Nehmt die klitzekleinen Schildkröten und kickt sie in das Wasser des Aschensees. Macht Euch keine Sorgen wegen des Kickens, sie haben harte Panzer.\n\nAußerdem haben sie ziemlich harte Zähne, Ihr solltet sie also nicht am Mund hochnehmen.", sourceObjective = "Kickt 5 Abkömmlinge von Tortolla ins Wasser.", completion = "<Mylunes Stimme schallt durch Euren Kopf, zusammen mit ungebetenen Bildern von verspielten Kätzchen.>\n\nIhr habt die klitzekleinen Schildkröten gerettet, {name}! Ich hoffe, der Tritt, den Ihr ihnen gegeben habt, war sanft, liebevoll und so fest wie möglich.", sourceObjectiveStatus = "unverified-source-field" }
quests[29102] = { id = 29102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Fort Livingston", description = "Zunächst sollt'n wir dort nachschau'n, wo sie vermutlich zuerst angreif'n werd'n. Der Ort nennt sich Fort Livingston.\n\nFort Livingston is' von Trollruinen umgeb'n... Und stellt ein einfaches Ziel dar.\n\nVielleicht find'n wir den Abgesandten dort. Hoffentlich is' es noch nich' zu spät.", sourceObjective = "Reist nach Fort Livingston im Nördlichen Schlingendorntal, um den Abgesandten der Dunkelspeere ausfindig zu machen.", completion = "Ein anderer Botschafter der Dunkelspeere ist hier vor einiger Zeit durchgekommen und hat uns gesagt, wir sollen auf der Hut sein.\n\nEr hat erwähnt, dass weitere Trolle auftauchen würden, aber nicht in Geistform und auch nicht, dass ein {class} ihn begleitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29103] = { id = 29103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlangen und Gift", description = "Dank der Warnung des Abgesandten konnten wir noch ein paar Abenteurer zur Verteidigung gewinnen. Aber wir haben erwartet, dass wir gegen Trolle kämpfen müssten, doch dann wurden wir von diesen Schlangen überwältigt!\n\nSie scheinen von überall her zu kommen. Wir können kaum noch durchhalten und ich fürchte, dass es nur noch schlimmer wird.\n\nHelft uns und eliminiert diese Schlangen... und vielleicht kann Eure Trollfreundin hier etwas Magie anwenden, um die Vergifteten zu heilen.", sourceObjective = "Tötet Dschungelschlangen und untersucht die vergifteten Abenteurer, damit Bwemba sie heilen kann.", completion = "Danke für Eure Hilfe, {class}. Die Schlangen sind ja überall.", sourceObjectiveStatus = "unverified-source-field" }
quests[29104] = { id = 29104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geister sind mit uns", description = "Mit den Schlangen hat was nich' gestimmt, {name}. In ihrem Gift war eine Spur von schlechtem Mojo und das passiert nich' von Natur aus.\n\nDas Freudenfeuer in der Mitte des Lagers - dort können wir ein Ritual abhalt'n.\n\nWas auch immer diese Schlangen zum Angreif'n bringt, passt bestimmt noch gut auf sie auf.\n\nDas einzige Problem is', {name}, dass ich nur in Geisterform hier bin. Du musst meine Hände sein. Geh zu dem Feuer und bereite es für mich vor. Dann kümmere ich mich um den Rest.", sourceObjective = "Bereitet das Freudenfeuer in Fort Livingston für Bwembas Ritual vor.", completion = "Venoxis... das kann nix Gutes heiß'n, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29105] = { id = 29105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nesingwary wird es wissen", description = "Großartig. Genau, was wir jetzt brauchen. Die Gurubashi sind auf dem Kriegspfad und benutzen Schlangen als erste Angriffswelle. Immerhin wissen wir Bescheid.\n\nWir können vermutlich davon ausgehen, dass die Jäger in Nesingwarys Expedition mehr darüber wissen. Und selbst, wenn nicht, wissen sie sicher eine gute Methode, wie man Schlangen loswird.\n\nMacht Euch dorthin auf den Weg und erzählt ihnen, was Ihr hier gesehen habt. Lasst sie wissen, dass die Trolle Schlangen als Waffen einsetzen.", sourceObjective = "Warnt die Jäger in Nesingwarys Expedition im Nördlichen Schlingendorntal.", completion = "Über die Schlangen wissen wir Bescheid, {name}. Aber da draußen lauert noch etwas anderes... Der Dschungel ist zum Leben erwacht, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[29106] = { id = 29106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der größte Diamant aller Zeiten!", description = "Ich habe gehört, dass Magni Bronzebart, der frühere König von Eisenschmiede, sich in einen riesigen Diamanten verwandelt hat! Stimmt das? Wie verwandelt man sich denn einfach so in einen Diamanten? Vielleicht muss man ja König sein, und deshalb hat es noch niemand vor ihm gemacht.\n\nGehen wir ihn besuchen? Er sollte in dem Teil von Eisenschmiede sein, der Altstadt von Eisenschmiede genannt wird, direkt unterhalb des Hohen Sitzes.", sourceObjective = "Bringt Euer Menschenwaisenkind in die Altstadt von Eisenschmiede unterhalb des Hohen Sitzes und besichtigt die letzte Ruhestätte von König Magni Bronzebart. Wenn Euer Waisenkind nicht bei Euch ist, wenn Ihr ankommt, solltet Ihr es herbeirufen.", completion = "König Magni wollte also gar kein Diamant werden? Das ist aber traurig.\n\nHe, Schamanen arbeiten doch ständig mit Steinen und der Erde, oder? Vielleicht können sie ihm eines Tages helfen, wieder ein Zwerg zu werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[29107] = { id = 29107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malfurion ist zurückgekehrt!", description = "Ich habe gehört, dass Malfurion Sturmgrimm aus dem Smaragdgrünen Traum zurückgekehrt ist. Ich weiß zwar nicht, wo das ist, aber es klingt ziemlich weit weg.\n\nJedenfalls soll er bei der Hohepriesterin oben im Tempel des Mondes in Darnassus sein. Meint Ihr, wir könnten ihn besuchen gehen? Er muss doch der mächtigste Druide in der Geschichte Azeroths sein!", sourceObjective = "Bringt Euer Menschenwaisenkind in den Tempel des Mondes in Darnassus, um Malfurion Sturmgrimm zu treffen. Wenn Euer Waisenkind nicht bei Euch ist, wenn Ihr ankommt, solltet Ihr es herbeirufen.", progress = "Meint Ihr, ich könnte eines Tages auch ein Druide sein?", completion = "Das war großartig! Habt Ihr gesehen, wie Malfurion diese Flügel auf mich gewirkt hat? Die anderen Waisenkinder werden es so schade finden, dass sie diesen Ausflug verpasst haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[29109] = { id = 29109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schließt Euch dem Konvoi von Mor'shan an", description = "Die Schlacht ums Eschental tobt stetig weiter. Unsere Streitkräfte am Schutzwall von Mor'shan brauchen dringend Verstärkung und Nachschub.\n\nWir haben hier eine große Ladung Medikamente und Nahrungsmittel, die nach Norden gebracht werden soll und ich brauche <einen fähigen/eine fähige:c> {class} wie Euch, <der/die:c> die Ladung bewacht.\n\nRocco Peitschenschwinger wartet auf Euch an der Straße, die nördlich aus dem Wegekreuz führt. Lasst ihn wissen, dass Ihr bereit seid, den Konvoi zu begleiten.", sourceObjective = "Sprecht mit Rocco Peitschenschwinger und fahrt mit dem Konvoi von Mor'shan nach Norden.", completion = "Das sind schreckliche Neuigkeiten! {name}, wenigstens seid Ihr sicher angekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29110] = { id = 29110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet den Konvoi von Mor'shan", description = "Sie haben Balgor und die Konvoigüter unter unserer Nase weggeschnappt!\n\nDiese Lieferung ist für den Sieg gegen die Allianz im Eschental unabdingbar und Balgor... wenn meinem lieben kleinen Bruder auch nur ein Haar gekrümmt wird, reiße ich persönlich jedes einzelne Mitglied der Brennenden Klinge in Stücke.\n\n{name}, Ihr müsst Balgor und die gestohlenen Güter retten. Folgt dem Pfad nördlich von uns zum Glutnebelgipfel. Lasst keinen einzigen dieser Hunde am Leben.", sourceObjective = "Rettet Balgor Peitschenschwinger.", completion = "{name}, Ihr eilt mir zur Rettung!", sourceObjectiveStatus = "unverified-source-field" }
quests[29111] = { id = 29111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt den Konvoi von Mor'shan durch", description = "Ihr habt es geschafft, den Unterschlupf der Brennenden Klinge aufzuscheuchen. Unsere Späher berichten, dass sie sich für einen Angriff sammeln.\n\nIhr müsst die Reise des Konvois abschließen, bevor sie hier ankommen. Die Vorräte sind verstaut, die Kodos sind ausgeruht und ich hoffe, Ihr habt nichts dagegen, dass ich ein paar Veränderungen an Eurem Gewehr vorgenommen habe.\n\nFalls wir auf Widerstand stoßen, solltet Ihr erst schießen und später Fragen stellen.\n\nSchnell! Da sind sie! Sprecht mit mir, wenn Ihr bereit zum Aufbruch seid.", sourceObjective = "Verteidigt den Konvoi von Mor'shan.", completion = "An manchen Tagen machen wir Boden gut, an anderen Tagen werden wir wieder hinter unsere Mauern zurückgedrängt. Und jeden Tag begraben wir mehr von unseren Brüdern und Schwestern.\n\n<Kadrak hält inne und atmet tief durch.>\n\nDass Ihr uns Nachschub gebracht habt, hat nicht nur unsere Truppen gestärkt, Eure Heldentaten haben ihnen auch neuen Mut gegeben. Danke, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29112] = { id = 29112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonensaat", description = "Hört her, {name}. Wir können noch nicht von hier weg. Ich habe ihre Pläne mitangehört, als sie das Ritual vorbereitet haben.\n\nSie haben vor, ein mächtiges Artefakt, das sie Dämonensaat nennen, dazu zu benutzen, einen Großangriff auf die Horde zu führen. Sie halten es dort drüben in der Höhle streng bewacht.\n\nWenn wir die Dämonensaat in unsere Hände bekommen können, sollten wir sie zu meiner Schwester Nagala bringen. Sie weiß sicher, was wir damit tun sollten.", sourceObjective = "Bringt die Dämonensaat in Euren Besitz.", progress = "Was habt Ihr auf der Spitze des Berges gefunden?", completion = "{name}, Ihr seid zurück! Balgor hat es vor Euch vom Berg geschafft und hat bereits zwei Schüsseln Raptoreintopf gegessen. Wenn sein Appetit ein Hinweis ist, wird er sicher bald reisebereit sein.\n\nIch werde sicherstellen, dass dieses Artefakt sicher verwahrt wird. Ihr habt uns heute einen großen Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29114] = { id = 29114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Spurenleser auf der Spur", description = "Wir schlagen hier schon seit Tagen die Schlangen zurück, {name}. Aber Schlangen sind nichts im Vergleich zu dem, was sich da sonst noch so im Dschungel herumtreibt.\n\nWir Jäger werden zu Gejagten.\n\nEin großer Panther namens Mauti hat meine Männer einen nach dem anderen in den Busch weggezerrt.\n\nWir haben Grent Düsterhammer, einen unserer besten Jäger, auf dieses Mistviech angesetzt.\n\nDüsterhammer ist nach Osten aufgebrochen. Vielleicht könnt Ihr ihn dort finden.", sourceObjective = "Findet Grent Düsterhammer im Nördlichen Schlingendorntal.", completion = "Schhh...", sourceObjectiveStatus = "unverified-source-field" }
quests[29115] = { id = 29115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rache des Jägers", description = "Die Bestie, die uns auf der Spur war... ich habe nach ihr gejagt.\n\nIhr Name ist Mauti. Sie ist ziemlich schlau. Doch sie hat einen großen Fehler begangen, als sie meinen Bruder getötet hat. Das wird sie teuer zu stehen kommen. Der alte Düsterhammer ist ihr auf den Fersen.\n\nIch habe sie oberhalb von Kurzens Truppenlager herumstreifen sehen. Wenn wir schnell zuschlagen, können wir ihr den Garaus machen.\n\nSeid Ihr bereit, {name}?", sourceObjective = "Gewährt Grent Düsterhammer die Genugtuung, die er sich wünscht, indem Ihr Mauti tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29116] = { id = 29116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Folgt dieser Katze", description = "Tja, deshalb schien Mauti wohl kleiner... Der echte Mauti hat sich mit Grent Düsterhammer davongemacht, aber da er so ein vorausschauender Jäger ist, hat er Signalfeuer abgeschossen, damit Ihr ihm auf der Spur bleiben könnt. Findet Düsterhammer, bevor es zu spät ist!", sourceObjective = "Findet heraus, wohin Mauti Grent Düsterhammer gebracht hat.", completion = "Da sind wir... Der Jäger, er is' in der Höhle. Die Bestie... Etwas stimmt mit ihr nicht...", sourceObjectiveStatus = "unverified-source-field" }
quests[29117] = { id = 29117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachensteigen", description = "Neulich, als ein paar von uns mit der Matrone unterwegs waren, haben wir einen Gnom gesehen, der einen Wagen mit Spielzeugen geschoben hat. Er hatte Puppen, Rennwagen aus Kupfer, Lederbälle und Papierdrachen. Ich wollte schon immer einen Drachen haben und die Matrone sagt, dass ich nur all mein Geld sparen muss, dann kann ich mir einen kaufen, aber das dauert noch ewig.\n\nIch glaube, der Name des Gnoms war Craggle Schlingerkreisel oder so was. Wenn wir ihn aufspüren, könnten wir uns ein paar Drachen holen und sie steigen lassen? Ich habe ihn die Kanäle um den Handelsdistrikt herum entlanggehen sehen.", sourceObjective = "Kauft einen Doppelpack Papierdrachen von Craggle Schlingerkreisel in Sturmwind und benutzt sie, um mit Eurem Menschenwaisenkind einen Drachen steigen zu lassen. Wenn Euer Waisenkind nicht bei Euch ist, solltet Ihr es herbeirufen.", completion = "Danke für den Drachen, {name}. Jedesmal wenn ich ihn steigen lasse, werde ich an den Tag denken, an dem Ihr ihn mir geschenkt habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[29118] = { id = 29118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Folgt dieser Katze", description = "Der echte Mauti hat sich mit Grent Düsterhammer davongemacht, aber da er so ein vorausschauender Jäger ist, hat er Signalfeuer abgeschossen, damit Ihr ihm auf der Spur bleiben könnt. Findet Düsterhammer, bevor es zu spät ist!", sourceObjective = "Findet heraus, wohin Mauti Grent Düsterhammer gebracht hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[29119] = { id = 29119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lecker Eis", description = "Es gibt einen brandneuen Eisladen in Sturmwind und dort verkaufen sie nicht einfach nur gewöhnliches Eis. Deren Eis wird von Magiern gemacht! Glaubt Ihr, es wird verschwinden, wenn ich es nicht innerhalb von fünfzehn Minuten schaffe?\n\nIch wette, das schmeckt richtig lecker. Gehen wir kosten?\n\nIch habe einige der anderen Kinder darüber reden hören und die sagen, der Laden heißt 'Der Kältekegel' und steht drüben beim Blauen Eremiten im Magierviertel.", sourceObjective = "Kauft ein Eis im Laden Kältekegel und teilt es mit Eurem Waisenkind.", progress = "Eiscreme mag ich am liebsten.", completion = "Meint Ihr, die Lehrlinge stört es, all das Eis einfrieren zu müssen? Ich wünschte, wir dürften in der Schule Eis machen. Dann wäre der Unterricht viel spannender, findet Ihr nicht?", sourceObjectiveStatus = "unverified-source-field" }
quests[29120] = { id = 29120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mauti", description = "Ich hab das Gefühl, dass mit dem Panther was nich' stimmt, {name}. Fühlt sich unnatürlich an. Ich werd' ein paar Rituale über dem Leichnam abhalt'n müss'n. Töte Mauti und dann werd'n wir mal seh'n, was wir herausfinden können, {name}.", sourceObjective = "Bringt Bwemba zu den Überresten von Mauti.", completion = "Hohepriesterin Kilnara steckt hinter dieser Monstrosität. Das sieht nich' gut aus. Wir sollt'n nach dem Zwerg seh'n und dann herausfind'n, was sonst noch so los ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[29121] = { id = 29121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzten Botten", description = "Ah... Ihr seid es, {name}. Mauti... Er ist tot? Dann wurde mein Bruder gerächt. Ich habe nur noch eine Bitte an Euch... Dieser Schuft hier hat an meinen nackten Füßen herumgekratzt. Kein Zwerg sollte ohne Stiefel unter die Erde müssen.\n\nBitte, begrabt mich mit meinen Stiefeln.", sourceObjective = "Holt die Stiefel von Grent Düsterhammer.", progress = "Habt Ihr meine Stiefel? Gewährt einem Zwerg doch seinen letzten Wunsch, ja?", completion = "Da-Danke... Kumpel.\n\nPapi...?\n\n\nBist...\n\n\n\ndu das...\n\n\n\n\n...", sourceObjectiveStatus = "unverified-source-field" }
quests[29122] = { id = 29122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echos von Nemesis", description = "<Mylunes Stimme singt wie eine Melodie in Eurem Kopf.>\n\nErinnert Ihr Euch an die furchtbare Feuerschildkröte, Nemesis, aus den Feuerlanden? Sie ist jetzt tot (hurra!), aber ihre Echos versuchen, zum Hyjal durchzubrechen.\n\nGeht zu den Ufern des Aschensees und sprecht mit meinem Freund Tooga. Lasst ihn wissen, wenn Ihr bereit seid, Euch einem Echo von Nemesis zu stellen und die Schildkröten werden es in diese Welt ziehen. Dann könnt Ihr es schlagen! Hart!\n\nVersteckt Euch in Toogas Panzer, wenn das Echo beginnt, auszubrechen.", sourceObjective = "Sprecht mit Tooga, um Nemesis zu beschwören und zu töten. Stellt Euch unter Toogas Panzer, um Euch vor Nemesis' 'Glühendem Zorn' zu schützen.", completion = "Hurra! Da sieht man mal wieder, wenn eine Schildkröte sich was vorgenommen hat, dann...\n\n<Mylune wird von einem Schmetterling abgelenkt und bringt den Gedanken niemals zu Ende.>", sourceObjectiveStatus = "unverified-source-field" }
quests[29123] = { id = 29123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturm gegen die Flammen", description = "Von all unseren Aufgaben hier am Hyjal ist die dringendste recht einfach: diese Eindringlinge zu vernichten. Es liegt in der Natur des Feuers, dass es alles und jeden verzehrt. Wenn Ihr in Eurer Verteidigung nur einen Moment nachlasst, wird es alles im Sichtbereich zerstören.\n\nVernichtet alle feurigen Eindringlinge, die Ihr findet. Jeder bezwungene Feind erkauft dem Hyjal mehr Zeit.", sourceObjective = "Tötet 6 beliebige Eindringlinge aus den Feuerlanden am Geheilten Hyjal oder in Sethrias Nest.", completion = "Ihr habt Euch gut geschlagen, {name}. Legt für eine Zeit eine Pause von den Flammen ein.\n\nDer Hyjal wird einen weiteren Tag erleben, und wenn dieser Tag anbricht, brauche ich Euch lebend.", sourceObjectiveStatus = "unverified-source-field" }
quests[29124] = { id = 29124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warnung an das Rebellenlager", description = "Dieser Tod is' nich' umsonst gewes'n, {name}. Wir hab'n herausgefund'n, dass Kilnara auf der Jagd ist. Das sieht alles gar nich' gut aus.\n\nWir sollt'n besser das Rebellenlager im Norden auskundschaft'n. Vielleicht find'n wir meinen Kontakt dort.", sourceObjective = "Begebt Euch zum Rebellenlager.", completion = "Erst sind es Schlangen, dann sind es Panther und dann haben wir es mit Trollen zu tun.\n\nBloß gut, dass Ihr hier seid. Wir können jede Hilfe brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29125] = { id = 29125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwischen den Bäumen", description = "Geisterfragmente von Malorne, die uns Sterblichen wie geisterhafte, weiße Hirsche erscheinen, tollen noch immer durch diese Wälder. Auch wenn Malorne nicht mehr unter uns weilt, könnten uns diese Geister von Nutzen sein.\n\nBegebt Euch nach Osten und wandelt unter diesen Bäumen. Wenn es Euch gelingt, nah genug an eines dieser Geisterfragmente heran zu kommen, so wird es seine Macht auf Euch übertragen.\n\nOh, und nehmt diesen Stab. Ihr könntet ihn später vielleicht brauchen.", sourceObjective = "Fangt drei Geister von Malorne, indem Ihr Euch in ihre Nähe bewegt.", completion = "<Direkt nachdem Ihr den letzten der Geister von Malorne berührt habt, hört Ihr Matooklas Stimme.>\n\nGut gemacht. Mit den Hörnern von Malorne an unserer Seite haben wir gegen einen der mächtigsten Bewohner der Feuerlande eine Chance: Galenges.", sourceObjectiveStatus = "unverified-source-field" }
quests[29126] = { id = 29126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht von Malorne", description = "<Matooklas Stimme fährt fort.>\n\nDas Portal, das sich östlich von uns geöffnet hat, wird von einem mächtigen Flammenschürer namens Galenges bewacht. Wir werden alles an Hilfe brauchen, was Malorne uns geben kann, um ihn zu bezwingen.\n\nErinnert Ihr Euch an den Stab, den ich Euch gegeben habe? Platziert ihn auf dem Aschehaufen vor dem Portal. Und dann betet, dass Malorne Euch zu Hilfe kommt.", sourceObjective = "Benutzt den Stab des Wächters um Galenges zu beschwören und zu bezwingen.", completion = "Galenges ist gefallen, das Unzerbrechliche wurde zerbrochen... aber noch ist unsere Arbeit nicht getan.", sourceObjectiveStatus = "unverified-source-field" }
quests[29127] = { id = 29127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturm gegen die Flammen", description = "Von all unseren Aufgaben hier am Hyjal ist die dringendste recht einfach: diese Eindringlinge zu vernichten. Es liegt in der Natur des Feuers, dass es alles und jeden verzehrt. Wenn Ihr in Eurer Verteidigung nur einen Moment nachlasst, wird es alles im Sichtbereich zerstören.\n\nVernichtet alle feurigen Eindringlinge, die Ihr findet. Jeder bezwungene Feind erkauft dem Hyjal mehr Zeit.", sourceObjective = "Tötet 8 beliebige Eindringlinge aus den Feuerlanden am Geheilten Hyjal oder in Sethrias Nest.", completion = "Ihr habt Euch gut geschlagen, {name}. Legt für eine Zeit eine Pause von den Flammen ein.\n\nDer Hyjal wird einen weiteren Tag erleben, und wenn dieser Tag anbricht, brauche ich Euch lebend.", sourceObjectiveStatus = "unverified-source-field" }
quests[29128] = { id = 29128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidiger des Hyjal", description = "Wir müssen mehr Druck auf den Angriffsstützpunkt in Sethrias Nest machen. Ragnaros' Diener nutzen diesen Bereich als Ausgangspunkt, um ihre Front über die Grenzen von Hyjal hinauszudrücken. Ich übertrage Euch das Kommando über einen kleinen Trupp, um es mit ihnen aufzunehmen.\n\nIch habe einen Elitetrupp von Kämpfern ausgewählt, um Euch zu unterstützen. Reist zu Sethrias Nest. Eure Mitstreiter haben den Befehl, Euch dort bei Eurer Ankunft zu treffen. Setzt den Angriffen der Elementare ein Ende.", sourceObjective = "Tötet 6 feurige Ungetüme oder wutentbrannte Pyrolords.", completion = "Ihr habt Euren Auftrag gut erledigt, Soldat. Obwohl unsere Mission in den Feuerlanden entscheidend ist, dürfen wir doch nicht das Wohlergehen des Hyjal vergessen.\n\nSprecht morgen erneut mit meinem Bruder und er wird einen weiteren Trupp für Euch bereit haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[29129] = { id = 29129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine legendäre Verabredung", description = "Es ist mir ein Vergnügen, {class}.\n\n<Ziradormi lächelt.>\n\nAus mir unbekannten Gründen wünscht mein Meister eine Audienz mit Euch.\n\nIch rate Euch, diese Einladung nicht auf die leichte Schulter zu nehmen. Anachronos hat nur selten einen Grund, direkten Kontakt mit Sterblichen zu suchen. Es wäre weise, ihn sofort in den Höhlen der Zeit aufzusuchen.\n\nSprecht mit mir, wenn Ihr bereit seid und ich werde Euch persönlich dorthin bringen.", sourceObjective = "Sprecht mit Anachronos in den Höhlen der Zeit.", completion = "Es ist keine launische Willkürlichkeit, die Euch hierhergeführt hat, Sterbliche.\n\nIhr müsst jedes letzte bisschen Mut für das aufbringen, was Ihr gleich sehen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29131] = { id = 29131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigt das Rebellenlager", description = "Wir sind hier in Schwierigkeiten, {name}. Euer Trollfreund ist hier durchgekommen und hat uns gewarnt, dass es bald ernst werden würde, aber ich habe nicht mit so etwas gerechnet.\n\nWir werden unser Bestes geben, um diese Trolle fernzuhalten, aber jede Hilfe, die Ihr anbieten könnt, wäre sehr willkommen.", sourceObjective = "Helft mit, das Rebellenlager drei Minuten lang zu verteidigen.", completion = "Danke, dass Ihr uns eine Verschnaufpause verschafft habt.\n\nWie ich schon sagte, war Euer Freund für kurze Zeit hier. Er hat uns gewarnt, dann ist er wieder aufgebrochen.\n\nJakob Windstill hat ihm geholfen, zu seinem nächsten Bestimmungsort zu kommen, vielleicht kann er Euch helfen.\n\nViel Glück, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29132] = { id = 29132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine legendäre Verabredung", description = "Ich habe mir schon gedacht, dass ich Euch hier treffen würde, {class}. Allerdings sind wir vom bronzenen Drachenschwarm da auch ein wenig im Vorteil, wenn es um solche Dinge geht.\n\n<Coridormi lächelt.>\n\nAus mir unbekannten Gründen wünscht mein Meister eine Audienz mit Euch.\n\nIch rate Euch, diese Einladung nicht auf die leichte Schulter zu nehmen. Anachronos hat nur selten einen Grund, direkten Kontakt mit Sterblichen zu suchen. Es wäre weise, ihn sofort in den Höhlen der Zeit aufzusuchen.\n\nSprecht mit mir, wenn Ihr bereit seid und ich werde Euch persönlich dorthin bringen.", sourceObjective = "Sprecht mit Anachronos in den Höhlen der Zeit.", completion = "Es ist keine launische Willkürlichkeit, die Euch hierhergeführt hat, Sterblicher.\n\nIhr müsst jedes letzte bisschen Mut für das aufbringen, was Ihr gleich sehen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29133] = { id = 29133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Grabungsstätte", description = "Der andere Abgesandte der Dunkelspeere war kurz hier. Er wollte dringend zum nächsten Ort, um die Leute dort zu warnen. Ich habe ihn auf einen Greifen zur Grabungsstätte der Forscherliga am Schlingendornkap gesetzt. Ich hoffe, er war nicht zu spät.\n\nIch gebe Euch einen meiner Greifen für einen Direktflug dorthin. Sprecht mit mir, wenn Ihr bereit seid, {name}.", sourceObjective = "Begebt Euch zur Grabungsstätte der Forscherliga am Schlingendornkap.", completion = "Das sieht nich' gut aus, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29134] = { id = 29134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Furche in der Zeit", description = "Hört gut zu, {class}, denn obwohl wir erst am Anfang stehen, wird die Zeit bereits knapp und die Folgen unseres Scheiterns sind unvorstellbar.\n\nEin Ereignis in der jüngsten Vergangenheit wurde durch mächtige Magie vor mir verschleiert.\n\nSeine Auswirkungen jedoch nicht.\n\nWenn nichts unternommen wird, um den Ablauf dieser Zeitlinie zu ändern, ist das Resultat klar.\n\nHaltet an Euch, <Sterblicher/Sterbliche>, und seht die Zukunft Azeroths.", sourceObjective = "Sprecht mit Anachronos in den Höhlen der Zeit, um <Zeuge/Zeugin> der Zukunft Azeroths zu werden.", progress = "Werdet Zeuge des Untergangs unserer Welt, {class}.", completion = "Jetzt, Sterblicher, kennt Ihr den Grund hinter meiner Einladung.", sourceObjectiveStatus = "unverified-source-field" }
quests[29135] = { id = 29135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein allsehendes Auge", description = "Ich kann die Fragen sehen, die Eure Gedanken in Aufruhr versetzen und ich muss gestehen, dass auch ich mir nicht sicher bin... eine ungewöhnliche Situation für jemanden wie mich und eine sehr beunruhigende.\n\nWährend ich die Zeit durchforste, um Spuren dieses verhüllten Ereignisses zu finden, müsst Ihr mir bei der Erschaffung eines Auges helfen. Dadurch werdet Ihr Eure Würdigkeit beweisen und ein wesentliches Werkzeug zur Entschlüsselung dieses Rätsels beschaffen.\n\nReist in die Elementarebene des Feuers, {class}, und sammelt Immerglut. Bringt mir diese sowie die Sande der Zeit und ich werde das Auge herstellen.", sourceObjective = "Sammelt 25 Stück Immerglut aus den Feuerlanden sowie 3 Handvoll Sande der Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[29137] = { id = 29137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lücke in der Verteidigung", description = "Lavawürmer brechen durch den Boden hinter unseren Reihen. Sie durchbrechen unsere Formationen und erlauben es Elementaren, hindurchzuschlüpfen. Ihr werdet sie über unsere gesamte Front im Norden und auf den Aschenfeldern weiter draußen finden.\n\nTrampelt sie zurück in ihre Löcher.", sourceObjective = "Tötet 5 Lavabohrer.", completion = "Wir sind dankbar für Eure Unterstützung. Eure Anwesenheit auf dem Schlachtfeld gibt uns genügend Zeit, uns neu zu sammeln. Eure Mühen sind das Zünglein an der Waage.", sourceObjectiveStatus = "unverified-source-field" }
quests[29138] = { id = 29138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brandopfer", description = "Wir haben Krieger draußen im Feld, die verwundet zu Boden gehen, und viele unserer Druiden sind zu beschäftigt mit dem Kampf, um ihnen die nötige Hilfe zukommen zu lassen. Ich möchte, dass Ihr nach Norden geht, in Richtung der Aschenfelder, und Euch zumindest so weit um ihre Wunden kümmert, dass sie sich in Sicherheit bringen können.\n\nSolltet Ihr über keine Verbände oder heilende Zauber verfügen, so nehmt diese Salbe, die ich Rayne habe herstellen lassen. Sie sollte ausreichen, damit sie wieder auf die Beine kommen.", sourceObjective = "Heilt 8 verwundete Verteidiger des Hyjal.", progress = "Zu unserem Glück verwunden Ragnaros' Streitkräfte unsere Krieger sehr viel häufiger, als dass sie sie direkt töten. Ihre Angriffe brennen die Wunden, die sie zufügen, auf natürliche Art und Weise aus. Das ist sehr schmerzhaft, aber es ist besser als zu sterben.", completion = "Ich habe mehrere unserer Krieger gesehen, wie sie kurz nach Eurem Aufbruch in Sicherheit gelangt sind. Eure Anstrengungen scheinen überaus effektiv gewesen zu sein. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[29139] = { id = 29139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aggressives Wachstum", description = "Unsere Krieger tun, was sie können, um diese Elementare zurückzuhalten, aber ihre Reihen sind endlos. Wir müssen etwas tun, um den Angriff zu verlangsamen.\n\nFindet passende Flecken von Erde oder Asche draußen in den Aschenfeldern im Norden von uns und pflanzt diese Samen. Aus ihnen werden tödliche Ranken erwachsen, die unsere Feinde vielleicht ein wenig verlangsamen. Das mag nicht viel sein, aber jede Kleinigkeit hilft.", sourceObjective = "Pflanzt 5 Stickrankensamen in den Aschehaufen in den Aschenfeldern.", completion = "Wir werden diese Schlacht gewinnen. Egal, was es uns abverlangt, wir werden diese Elementare nicht wieder auf den Hyjal lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29140] = { id = 29140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ns Feuer" }
quests[29141] = { id = 29141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallhöhe", description = "Geschmolzene Ungetüme haben sich den Elementaren auf dem Schlachtfeld angeschlossen. Sie zermalmen unsere Frontlinien. Ich brauche Euch, um ihrer Wucht Einhalt zu gebieten.\n\nIhr werdet sehen, die Bestien sind zwar langsam und ungeschickt und sie lassen sich leicht ausmanövrieren, aber wenn sie Euch treffen, dann mit zerstörerischer Kraft. Bleibt in Bewegung, {class}.", sourceObjective = "Tötet 3 geschmolzene Ungetüme.", completion = "Die Elementare werden lernen, Euch zu fürchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29142] = { id = 29142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr der Verräter", description = "Die Druiden der Flamme greifen unsere Frontlinie an, {name}.\n\nDiese üblen Kreaturen haben Elunes Lehren den Rücken zugewandt und verehren stattdessen den Feuerfürsten Ragnaros. Von seiner wahnsinnigen Macht verdorben, ersehnen sie nichts so sehr, wie uns in Asche zu begraben.\n\nWir müssen ihrem Angriff sofort etwas entgegensetzen!", sourceObjective = "Tötet 3 Druiden der Flamme.", completion = "Gut. Unsere Feinde wissen jetzt, dass sie unsere Stärke fürchten sollten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29143] = { id = 29143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irrwische los", description = "Die Feuerelementare ergießen sich aus den Portalen jenseits der Aschenfelder. Wir brauchen jemanden, der sie schließt und ihnen die Verstärkung abschneidet.\n\nFür das Bannen dieser Art von elementarer Magie sind unsere Irrwische perfekt geeignet. Einer von ihnen wird Euch begleiten. Führt ihn zu einem Portal und haltet ihn am Leben, bis er seine Aufgabe beendet hat.", sourceObjective = "Führt einen Irrwisch des Hyjal zu einem der Feuerportale in den Aschenfeldern und beschützt den Irrwisch, bis er das Portal geschlossen hat. Solltet Ihr Euren Irrwisch verlieren, so solltet Ihr zu Rayne Federsang bei Malfurions Bresche zurückkehren.", completion = "Gut gemacht, {class}. Ich werde Eure Fähigkeiten in Zukunft noch öfter einsetzen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29144] = { id = 29144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufräumen in Sturmwind", description = "Grüße, {class}! Genießt Ihr die Schlotternächte? Offenbar hat sich die Horde nach unserem Stinkbombenabwurf auf Unterstadt dazu entschlossen, unsere Stadt auch zu bombardieren. Die Stinkbomben, die sie benutzen, sind stärker als die, die sie letztes Jahr verwendet haben. Die Kraft der Pinie wird nicht genug sein. Wir brauchen etwas mit mehr Wumms. Benutzt dieses arkane Reinigungsmittel, um die Stinkbomben aus der Stadt zu beseitigen.", sourceObjective = "Benutzt den Arkanreiniger, um die Stinkbomben rund um Sturmwind zu entfernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29145] = { id = 29145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Öffnen der Tür", description = "Ihr kommt ein wenig spät. Hamuul, Malfurion und einige unserer geschätzten Gäste sind bereits zum Invasionspunkt, oben auf der Klippe, gereist.\n\nUnser Tor zu den Feuerlanden ist noch nicht fertig, aber es wird es in Kürze sein. Je eher wir durchbrechen können, umso besser.\n\nGeht! Hamuul wird Euch schon erwarten.", sourceObjective = "Meldet Euch bei dem Erzdruiden Hamuul Runentotem am Nordunegrat auf dem Hyjal.", completion = "{name}. Es ist gut, Euch wiederzusehen. Unser Tor ist fast offen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29146] = { id = 29146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ritt auf der Raketenbahn", description = "Ich habe gehört, dass die neusten Mitglieder der Horde, die Goblins, eine verrückte Straße nur für Raketen in Azshara gebaut haben! Könnt Ihr Euch das vorstellen? Seit ich davon gehört habe, will ich mal dorthin. Ich habe Matrone Schlachterbe danach gefragt, und sie sagt, man nennt es die Raketenbahn!\n\nSie hat mir sogar erzählt, dass sie an einem Zweisitzer-Prototyp arbeiten. Wollen wir dort mal hinreisen und nachsehen, ob wir ihn ausprobieren können? Ich wette, die experimentelle Rakete ist in der Nähe vom Geheimlabor am südlichen Ende der Raketenbahn...", sourceObjective = "Reist zur Südlichen Endhaltestelle der Raketenbahn in Azshara und steigt in den Windhund-Zweisitzer-Prototyp an der Spitze des Turms.", progress = "Das wird die beste Kinderwoche aller Zeiten!", completion = "Das war toll! Ich habe sogar gelernt, wie man die Rakete steuert und so! Habt Ihr gesehen, wie ich uns gerettet habe? Wenn ich groß bin, werde ich ein Raketenpilot!", sourceObjectiveStatus = "unverified-source-field" }
quests[29147] = { id = 29147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarmruf", description = "Heute haben wir die Gelegenheit, einen weiteren Angriff gegen einen von Ragnaros' mächtigeren Dienern zu führen: Millagazor. Allerdings müssen wir uns zunächst Unterstützung besorgen.\n\n<Matookla hält eine große, seidene Feder hoch.>\n\nBenutzt dieses Artefakt, um die Macht von Aviana zu beschwören. Habt Ihr das getan, so reist gen Nordwesten und versammelt einige der ihren, indem Ihr ihnen zuruft.\n\nSobald Ihr das getan habt, werden wir gegen Millagazor ziehen können.", sourceObjective = "Benutzt Eure Fähigkeit 'Schwarmruf' um 12 Gebirgssingvögel, 5 Waldeulen und 2 Goldschwingenfalken einzusammeln.", completion = "<Zwischen dem Gezwitscher, Eulengeheul und hektischen Krächzen Eurer Vogelkollegen hört Ihr aus der Ferne die Stimme von Matookla zu Euch sprechen.>\n\nGut gemacht, {race}. Nun da der Schwarm versammelt ist, schlagen wir zu.", sourceObjectiveStatus = "unverified-source-field" }
quests[29149] = { id = 29149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturm gegen die Flammen", description = "Von all unseren Aufgaben hier am Hyjal ist die dringendste recht einfach: diese Eindringlinge zu vernichten. Es liegt in der Natur des Feuers, dass es alles und jeden verzehrt. Wenn Ihr in Eurer Verteidigung nur einen Moment nachlasst, wird es alles im Sichtbereich zerstören.\n\nVernichtet alle feurigen Eindringlinge, die Ihr findet. Jeder bezwungene Feind erkauft dem Hyjal mehr Zeit.", sourceObjective = "Tötet 7 beliebige Eindringlinge aus den Feuerlanden am Geheilten Hyjal oder in Sethrias Nest.", completion = "Ihr habt Euch gut geschlagen, {name}. Legt für eine Zeit eine Pause von den Flammen ein.\n\nDer Hyjal wird einen weiteren Tag erleben, und wenn dieser Tag anbricht, brauche ich Euch lebend.", sourceObjectiveStatus = "unverified-source-field" }
quests[29150] = { id = 29150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voodoozombies", description = "Die Leute... alles Zombies, Voodoozombies! Das wird nich' schön, {name}.\n\nDu musst die alle töt'n.\n\nAber sobald sie erledigt sind, gibt es einen Weg, wie ich sie zurückhol'n kann. Wieder in die Personen verwandeln, die sie war'n.\n\nWir müss'n schnell handeln, die Zombies schlafen nich'.", sourceObjective = "Rettet 10 Überlebende der Grabungsstätte.", completion = "Wir hab'n getan, was wir konnt'n, {name}. Wir können diese Zombies nich' länger bekämpf'n. Wir müss'n die Wurzel dieses Voodoos ausfindig mach'n. Und ich glaub', ich weiß, wo wir anfang'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[29151] = { id = 29151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdorbene Vorräte", description = "Einige der Überlebenden hab'n Nahrungsmittel erwähnt, {name}. Wir sollt'n ihre Vorräte überprüf'n. Ich hab ein schlechtes Gefühl bei der Sache.", sourceObjective = "Überprüft die Nahrungsvorräte bei der Grabungsstätte der Forscherliga.", completion = "Zanzil... Es fängt alles an, Sinn zu ergeb'n. Wenn ich meinen Kontakt find'n kann, können wir einen Angriffsplan entwickeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[29152] = { id = 29152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kontaktaufnahme", description = "Ihr seid keiner von den Zombies...\n\nEin Troll? Ich habe einen gesehen, direkt vor dem Ausbruch... Er hat uns gewarnt, gesagt, dass wir vorsichtig sein sollen... Aber es war zu spät.\n\nEuer Trollfreund ist nach Beutebucht gegangen, um sie zu warnen...", sourceObjective = "Begebt Euch nach Beutebucht und findet Bwembas Kontaktperson.", completion = "Ich werde Baron Revilgaz jetzt von der Zandalaribedrohung erzählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29153] = { id = 29153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Interessen Beutebuchts", description = "Also, {name}. Ihr habt uns schon gewaltig geholfen, aber das wird noch nicht reichen. Diese verrückten Trolle müssen aufgehalten oder zumindest von Beutebucht ferngehalten werden.\n\nIch werde jemanden losschicken, der das Geschehen im Auge behält, aber von Euch möchte ich, dass Ihr in Zul'Gurub eindringt und die Dinge in Bewegung setzt.\n\nIhr müsst mir zumindest etwas bringen, das diese Trolle aus Beutebucht fernhält.\n\nBringt das zustande und wir werden uns erkenntlich zeigen.", sourceObjective = "Spürt ein Artefakt auf, das die Trolle aus Zul'Gurub von Beutebucht fern halten könnte.", progress = "Habt Ihr etwas gefunden, {name}?", completion = "Ihr habt sie alle getötet? Ich wünschte, das wäre genug, um mir keine Sorgen mehr zu machen. Aber diese Typen scheinen die Angewohnheit zu haben, von den Toten zurückzukehren.\n\nAh, was habt Ihr denn da?\n\nIhr meint, das könnte sie aus Beutebucht fernhalten?\n\nSo kommen wir ins Geschäft!\n\nOh, sagte ich, dass ich eine Belohnung für Euch habe? Natürlich... gebt mir nur einen Moment, um die Belohnung zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29154] = { id = 29154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Interessen Beutebuchts", description = "Ich wurde von Baron Revilgaz aus Beutebucht hergeschickt, damit ich sicherstelle, dass diese Trollbedrohung aufgehalten wird. Oder dass sie zumindest vor den Toren von Beutebucht aufgehalten wird.\n\nIch will Taten und Ergebnisse sehen.\n\nIhr geht da jetzt für mich rein und veranstaltet ein Gemetzel.\n\nIhr geht da jetzt rein und sucht mir etwas, das diese Trolle aus Beutebucht fernhält.\n\nBringt das zustande und wir werden uns erkenntlich zeigen.", sourceObjective = "Spürt ein Artefakt auf, das die Trolle aus Zul'Gurub von Beutebucht fern halten könnte.", progress = "Habt Ihr etwas gefunden, {name}?", completion = "Ihr habt sie alle getötet? Ich wünschte, das wäre genug, um mir keine Sorgen mehr zu machen. Aber diese Typen scheinen die Angewohnheit zu haben, von den Toten zurückzukehren.\n\nAh, was habt Ihr denn da?\n\nIhr meint, das könnte sie aus Beutebucht fernhalten?\n\nSo kommen wir ins Geschäft!\n\nOh, sagte ich, dass ich eine Belohnung für Euch habe? Natürlich... gebt mir nur einen Moment, um die Belohnung zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29155] = { id = 29155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine glitzernde Beute", description = "Es gibt etwas Plündergut innerhalb der Statue auf der Janeirospitze, gleich nordwestlich von Beutebucht im Schlingendorntal.\n\nBegebt Euch zur Statue und nehmt Euren Preis an Euch, {class}.", sourceObjective = "Holt Euch Eure Belohnung aus einer Kiste in der Statue auf der Janeirospitze.", completion = "Endlich Beute!", sourceObjectiveStatus = "unverified-source-field" }
quests[29156] = { id = 29156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollinvasion", description = "Eine Gruppe von Trollen, die behaupten, für die Dunkelspeere zu sprechen, sind im Hafen von Sturmwind angekommen. Unsere Wachen halten sie fürs Erste zurück.\n\nDie Hafenwachen von Sturmwind suchen nach kampferprobten Abenteurern, die dabei helfen, diese Trolle zu entfernen. Meldet Euch bei Kommandant Spitz im Hafen von Sturmwind.", sourceObjective = "Sprecht mit Kommandant Spitz im Hafen von Sturmwind.", completion = "Ah gut, ein {class}. Vielleicht habt Ihr ja mehr Erfolg mit diesen Trollen.\n\nFindet heraus, was sie wollen, und seht dann zu, dass Ihr sie loswerdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29157] = { id = 29157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zandalari-Bedrohung", description = "Die Zandalaritrolle sind im Schlingendorntal auf dem Vormarsch!\n\nWenn Ihr den Dunkelspeeren helfen wollt, meldet Euch bei Bwemba in Orgrimmars Tal der Geister.", sourceObjective = "Sprecht mit Bwemba in Orgrimmars Tal der Geister.", completion = "Grüße, {race}. Wir leb'n in verzweifelten Zeiten. Die Zandalaritrolle sind dabei, ihre Ländereien zurückzuerobern.", sourceObjectiveStatus = "unverified-source-field" }
quests[29158] = { id = 29158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Abgesandte der Zandalari", description = "{class}! Hört meinen Ruf. Das Schlingendorntal benötigt Eure Hilfe! Kommt zu mir am Hafen.", sourceObjective = "Trefft Euch mit Bwemba im Hafen von Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[29159] = { id = 29159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pyrorachnophobie", description = "Wir haben hart darum gekämpft, diese Gegend zu sichern, aber unser Stand hier ist unsicher.\n\nUnsere Späher haben berichtet, dass es in der Gegend um uns herum vor bösartigen Feuerspinnen nur so wimmelt. Sie sind die Nachkommen der üblen Brutwitwe Beth'tilac.\n\nHelft uns, unsere Stellung zu halten, indem Ihr die Gegend von Aschenweberspinnern oder -krabblern befreit. Es wird sie wahnsinnig machen, ihre Kinder erschlagen zu sehen.", sourceObjective = "Tötet 8 Aschenweberspinner oder -krabbler.", completion = "Wundervoll! Je mehr Spinnen wir loswerden, desto einfacher wird es sein, voranzukommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29160] = { id = 29160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ver-ei-teln", description = "Wir haben hier ein echtes Problem an den Händen. Die Spinnen in der Nähe sind nicht nur bösartig und räuberisch, es scheint von ihnen auch endlos viele zu geben.\n\nWir müssen das Wachstum ihrer Armee aufhalten. Wir müssen ihnen die Köpfe schon in den Eiern abschlagen, nicht erst auf dem Schlachtfeld.\n\nDie Eier der Aschenweberspinner liegen zwischen den Steinsäulen im Norden. Sammelt 20 Eier ein und bringt sie mir.", sourceObjective = "Sammelt 20 Aschenweber-Eier von den Säulen im Gelege der Witwe.", progress = "Es scheint, als seien die Aschenweberspinner die Wärter von Beth'tilacs Brut.", completion = "Phantastische Arbeit, {class}. Wollen wir hoffen, dass diese kleinen Spinnenbisse nicht ansteckend sind.", sourceObjectiveStatus = "unverified-source-field" }
